/* Paused character sheet, inventory and explicit breakthrough confirmation. */
const CharacterUI=(()=>{
  let before='playing',tab='stats',giftDraft=null,giftError='';
  const n=v=>Number(v.toFixed(2)).toLocaleString('zh-CN');
  function init(){document.getElementById('characterBtn').onclick=toggle;}
  function toggle(){
    if(G.state==='character'){close();return;}
    if(!['playing','paused','win'].includes(G.state))return;
    before=G.state;clearInput();G.state='character';tab='stats';giftDraft=null;giftError='';draw();
  }
  function close(){if(G.state!=='character')return;clearInput();document.getElementById('overlay').classList.add('hidden');G.state=before==='paused'?'playing':before;if(before==='paused')togglePause();if(before==='win'){G.state='win';Journey.showEnd(true);}RunSave.save('关闭人物');}
  function draw(){
    if(G.state!=='character')return;
    const c=P.cultivation,r=Cultivation.recipe(),caps=Cultivation.caps(),ov=document.getElementById('overlay');
    ov.classList.remove('hidden','journey-screen','title-screen');
    const row=(name,current,limit,suffix='')=>`<div class="attribute-row"><span>${name}</span><b>${n(current)}${suffix}</b><small>上限 ${n(limit)}${suffix}</small></div>`;
    const stats=row('生命',P.hp,P.maxHp)+row('生命上限',P.maxHp,caps.maxHp)+row('护盾',P.shield,P.shieldMax)+row('护盾上限',P.shieldMax,caps.shieldMax)+row('伤害倍率',P.dmg,caps.dmg,'×')+row('暴击率',P.crit*100,caps.crit*100,'%')+row('受到伤害减免',P.armor*100,caps.armor*100,'%')+row('冷却缩减 · 含大招',(1-P.cdr)*100,(1-caps.cdr)*100,'%')+row('移速',P.speed,caps.speed)+row('拾取范围',P.pickup,caps.pickup)+row('护盾回复 / 秒',P.regen,caps.regen)+row('经验倍率',P.xpMul,caps.xpMul,'×');
    const spells=Object.entries(P.spells).map(([id,level])=>`<div class="inventory-item"><b>${SPELLS[id].name} · Lv.${level}</b><small>${SpellGrowth.describe(id,level)} · 上限 Lv.${Math.max(level,SpellGrowth.cap())}</small></div>`).join('');
    const equips=P.equips.map(id=>{const e=EQUIPS.find(e=>e.id===id);return `<div class="inventory-item"><b>${ItemCatalog.icon(e.id,e.name)}${e.name}</b><small>${e.desc}</small></div>`;}).join('')||'<p>暂无法宝</p>';
    const materials=[['essence','灵蕴精华'],...Cultivation.cores.map((name,i)=>['core'+(i+1),name])].map(([id,name])=>`<div class="material-item">${ItemCatalog.icon(id,name)}<span>${name}<small>${ItemCatalog.meta(id).use}</small></span><b>${c.materials[id]||0}</b></div>`).join('');
    let body=tab==='stats'?`<div class="character-constellation"><div class="hero-survival">${row('生命',P.hp,P.maxHp)}${row('生命最大值',P.maxHp,caps.maxHp)}${row('护盾',P.shield,P.shieldMax)}${row('护盾最大值',P.shieldMax,caps.shieldMax)}${row('减伤',P.armor*100,caps.armor*100,'%')}${row('正常回盾 / 秒',P.regen,caps.regen)}${row('交战回盾 / 秒',P.regen*.25,caps.regen*.25)}<p class="sheet-note">${CombatScaling.regenState().wait>0?'受伤后等待 '+CombatScaling.regenState().wait.toFixed(1)+' 秒恢复':CombatScaling.regenState().engaged?'交战回盾 · 正常速率的25%':'正常回盾'} · ${CombatScaling.hud()}</p></div><div class="hero-stage"><div class="hero-stage-title">${RealmVisuals.get(c).motif}</div><canvas id="heroPreview" width="340" height="430" aria-label="${HeroIdentity.get(P.heroId).name}当前境界动态展示"></canvas><div class="hero-realm">${Cultivation.label()}</div><div class="hero-equipment-slots">${Array.from({length:8},(_,i)=>{const equip=EQUIPS.find(e=>e.id===P.equips[i]);return `<span title="${equip?equip.name+'：'+equip.desc:'法宝空位'}">${equip?ItemCatalog.icon(equip.id,equip.name):'◇'}<small>${equip?equip.name:'法宝'}</small></span>`;}).join('')}</div></div><div class="hero-offense">${row('伤害倍率',P.dmg,caps.dmg,'×')}${row('暴击',P.crit*100,caps.crit*100,'%')}${row('冷却缩减 · 含大招',(1-P.cdr)*100,(1-caps.cdr)*100,'%')}${row('移速',P.speed,caps.speed)}${row('拾取范围',P.pickup,caps.pickup)}${row('经验倍率',P.xpMul,caps.xpMul,'×')}</div></div><p class="sheet-note">属性显示当前值 / 当前最大值或境界上限 · 每层灵纹增强 · 每境独立法相</p><p class="sheet-note">${Cultivation.autoStatus()}</p><h3>已习术法</h3><div class="inventory-grid">${spells}</div><h3>携行大招 · 独立剑意 / 冷却</h3><div class="inventory-grid">${UltimateArts.sheet()}</div><h3>携行法宝</h3><div class="inventory-grid">${equips}</div>`:tab==='bag'?`<h3>天材地宝</h3><p class="sheet-note">对应关卡大妖30%概率掉落本境破境宝物；域外超级大妖生命与伤害均为2倍，胜利100%获得核心材料和灵蕴各50%配方。普通妖怪与精英可补充灵蕴。本轮已领稀有奖励不会因刷新或死亡重发。</p><div class="material-grid">${materials}</div>`:'';
    if(tab==='spells'){
      if(!giftDraft)giftDraft={...SpellGift.ensure().levels};
      const current=SpellGift.effective(),draft=SpellGift.effective(giftDraft),safe=SpellGift.safe()&&!RunSave.conflicted();
      body=`<div class="gift-heading"><div><span class="overline">大境界突破赠礼 · 可暂存</span><h3>境界赠送升级：剩余 ${SpellGift.remaining(giftDraft)} 次</h3><p>每次破境获得三次术法升级 · 共获得 ${3*c.realm} 次</p></div><button id="resetGiftBtn">撤回赠送升级 · 预览</button></div><p class="sheet-note">本境术法上限 Lv.${SpellGrowth.cap()}；每次突破上限 +3级${c.realm<13?'，下一境开放至 Lv.'+SpellGrowth.cap(c.realm+1):''}。飞剑、万剑与五雷加强数量，其余术法扩大作用距离或范围。万剑每五级展开新圈，每级增加剑数。每次增加一级，最多携带六门；普通升级与宝箱成长永久保留。安全时免费调整，确认前不影响战斗。新加入术法从完整冷却开始。</p><div class="gift-grid">${SpellGift.keys.map(key=>{const old=current[key]||0,l=draft[key]||0,base=SpellGift.base()[key]||0;return `<article class="gift-card" style="--spell:${SPELLS[key].color}"><header><b>${SPELLS[key].glyph} ${SPELLS[key].name}</b><strong>${old?'Lv.'+old:'未习得'} → ${l?'Lv.'+l:'未习得'}</strong></header><small>${SpellGrowth.focus(key)} · 永久 ${base}级 · 赠送 ${giftDraft[key]||0}级 · 上限 ${Math.max(base,SpellGrowth.cap())}级</small>${RewardCards.spellHTML(key,old,l)}<p class="gift-change">${SpellGrowth.change(key,old,l)}</p><div class="gift-controls"><button data-gift-minus="${key}" aria-label="撤回${SPELLS[key].name}一级" ${!giftDraft[key]?'disabled':''}>−</button><span>${giftDraft[key]||0} 次赠送</span><button data-gift-plus="${key}" aria-label="升级${SPELLS[key].name}一级" ${!SpellGift.canAdd(giftDraft,key)?'disabled':''}>＋</button></div></article>`;}).join('')}</div><p id="giftError" role="status">${giftError||(!safe?'脱离首领战且附近650范围内无交战妖怪后，才可确认调整。':'当前安全，可以确认调整。')}</p><button class="btn" id="applyGiftBtn" ${!safe?'disabled':''}>确认本次术法调整</button>`;
    }
    if(tab==='break'){
      if(c.result){const outcome=c.result;body=`<div class="break-result ${outcome.success?'success':''}"><span class="overline">第 ${outcome.attempt} 次破境 · 已结算</span><h3>${outcome.success?'破境已成 · '+Cultivation.realms[outcome.target]:'气机未合 · 此次未成'}</h3><canvas id="heroPreview" class="break-hero" width="340" height="430" aria-label="突破后法相展示"></canvas><p>本次成功率 ${outcome.chance}% · 消耗修为 ${n(outcome.loss)}</p><p>${outcome.success?'境界、基础属性和上限已提高，获得三次术法升级。':'只消耗本次投入材料与少量修为；境界、术法和法宝均保留。'}</p><button class="btn" id="ackBreakBtn">查看修炼状态</button></div>`;}
      else if(!r)body='<div class="break-result success"><h3>仙王 · 道圆</h3><p>已达修炼终境；仙王仍可积累修为，修至九层道圆。不再开放下一境突破。</p></div>';
      else {const core=Math.min(c.materials[r.core]||0,r.coreCount),essence=Math.min(c.materials.essence||0,r.essence);body=`<div class="break-heading"><span>${Cultivation.label()} →</span><h3>${Cultivation.realms[r.target]}</h3></div><p>突破修为 ${n(c.qi)} / ${n(r.qi)} · 失败损失 ${n(r.qi*.1)} 修为</p><div class="break-recipe"><label>${r.name}<small>背包 ${c.materials[r.core]||0} / 所需 ${r.coreCount}</small><input id="breakCore" aria-label="投入核心材料数量" type="number" min="0" max="${core}" value="${core}" step="1"></label><label>灵蕴精华<small>背包 ${c.materials.essence||0} / 所需 ${r.essence}</small><input id="breakEssence" aria-label="投入灵蕴精华数量" type="number" min="0" max="${essence}" value="${essence}" step="1"></label></div><p class="sheet-note">${r.name}：${Cultivation.realms[r.target-1]}对应关卡大妖30%掉落；域外超级大妖100%获得${r.coreCount/2}份核心与${r.essence/2}份灵蕴（配方各50%，生命与伤害2倍）。九层圆满后可突破。材料备齐且修为达标会在安全时自动突破；缺材可冒险，投入材料无论成败均消耗。</p><div class="break-preview"><strong id="breakChance"></strong><span>成功后：生命与护盾上限基础 +12% · 伤害 +8%</span><span>新生命上限封顶 ${n(Math.max(caps.maxHp,600*1.28**r.target))} · 新伤害倍率封顶 ${n(Math.max(caps.dmg,8*1.22**r.target))}×</span></div><p id="breakError" role="status"></p><button class="btn" id="attemptBreakBtn" ${!Cultivation.safe()||c.layer!==9||c.qi<r.qi||RunSave.conflicted()||Cultivation.ready()?'disabled':''}>${Cultivation.ready()?'材料备齐 · 将自动突破':'投入上述材料 · 冒险突破'}</button><p class="sheet-note">${World.active()?'首领战中不可突破。':!Cultivation.safe()?'附近尚有妖众交战，请脱离战斗后再突破。':c.qi<r.qi?'修为尚未达标，继续斩妖积累。':'当前处于安全状态。'} ${Cultivation.autoStatus()} · ${RunSave.status()}</p>`;}
    }
    ov.innerHTML=`<div class="panel character-panel"><header class="character-header"><div><span class="overline">无籍剑仙 · ${HeroIdentity.get(P.heroId).name}</span><h2>${Cultivation.label()}</h2><p>战斗等级 Lv.${P.level} · 经验 ${n(P.xp)} / ${n(P.xpNext)} · 剑意 ${n(P.energy)}%</p></div><button id="closeCharacterBtn" aria-label="关闭人物面板">×</button></header><div class="cultivation-meter"><i style="width:${Math.min(100,c.qi/Cultivation.need(c)*100)}%"></i><span>${'本境修为 '+n(c.qi)+' / '+n(Cultivation.need(c))+' · '+(c.qi>=Cultivation.need(c)?'九层圆满':c.layer+' / 9层')}</span></div><nav class="character-tabs">${[['stats','人物状态'],['spells','术法赠礼 · '+SpellGift.remaining()],['bag','天材地宝'],['break','境界突破']].map(([id,name])=>`<button data-sheet="${id}" aria-pressed="${id===tab}">${name}</button>`).join('')}</nav><section class="character-content">${body}</section><footer class="sheet-note">${RunSave.status()} · C / Esc 关闭 · 面板开启时战斗暂停</footer></div>`;
    document.getElementById('closeCharacterBtn').onclick=close;
    ov.querySelectorAll('[data-sheet]').forEach(button=>button.onclick=()=>{tab=button.dataset.sheet;draw();});
    if(tab==='spells'){
      ov.querySelectorAll('[data-gift-plus]').forEach(b=>b.onclick=()=>{const key=b.dataset.giftPlus;if(SpellGift.canAdd(giftDraft,key))giftDraft[key]=(giftDraft[key]||0)+1;giftError='';draw();});
      ov.querySelectorAll('[data-gift-minus]').forEach(b=>b.onclick=()=>{const key=b.dataset.giftMinus;if(giftDraft[key])giftDraft[key]--;if(!giftDraft[key])delete giftDraft[key];giftError='';draw();});
      document.getElementById('resetGiftBtn').onclick=()=>{giftDraft={};giftError='当前仅预览撤回，确认后生效。';draw();};
      document.getElementById('applyGiftBtn').onclick=()=>{giftError=SpellGift.apply(giftDraft)?'术法调整已保存。':'调整未执行：'+RunSave.status();draw();};
    }
    if(tab==='break'&&c.result)document.getElementById('ackBreakBtn').onclick=()=>{c.result=null;RunSave.save('确认突破结果');draw();};
    else if(tab==='break'&&r){
      const a=document.getElementById('breakCore'),b=document.getElementById('breakEssence'),rate=document.getElementById('breakChance');
      const update=()=>{rate.textContent='本次成功率 '+Cultivation.chance(Math.max(0,Math.min(Number(a.value)||0,Number(a.max))),Math.max(0,Math.min(Number(b.value)||0,Number(b.max))))+'%';};a.oninput=b.oninput=update;update();
      document.getElementById('attemptBreakBtn').onclick=()=>{if(Cultivation.attempt(Number(a.value),Number(b.value)))draw();else document.getElementById('breakError').textContent=RunSave.conflicted()?'另一窗口已更新，请载入最新存档。':'突破未执行：请检查材料、修为、安全状态与存储权限。';};
    }
  }
  function coreRewardHTML(){if(!G.coreReward)return '';const target=G.coreReward.max;return `<div class="core-reward"><h3>守关天材地宝 · 定向领取</h3><div class="core-portrait" id="corePortrait">${ItemCatalog.icon('core'+target,Cultivation.cores[target-1])}</div><div id="corePreview">${RewardCards.coreHTML(target,G.coreReward.count||1)}</div><p>${Cultivation.realms[ChapterCatalog.get(Journey.run.stage).realm]}篇守关奖励 · 领取后才可继续前行</p><select id="bossCoreSelect" aria-label="选择首领核心材料">${Cultivation.cores.slice(0,target).map((name,i)=>`<option value="${i+1}" ${i+1===target?'selected':''}>${name} ×${G.coreReward.count||1} · 用于突破${Cultivation.realms[i+1]}</option>`).join('')}</select><button class="btn" id="claimBossCoreBtn">收下所选天材地宝</button></div>`;}
  function bindCoreReward(){if(G.coreReward){const select=document.getElementById('bossCoreSelect');select.onchange=()=>{document.getElementById('corePreview').innerHTML=RewardCards.coreHTML(Number(select.value),G.coreReward.count||1);document.getElementById('corePortrait').innerHTML=ItemCatalog.icon('core'+select.value,Cultivation.cores[Number(select.value)-1]);};document.getElementById('claimBossCoreBtn').onclick=()=>Cultivation.claimCore(Number(select.value));}}
  function decorateMenu(){
    const ov=document.getElementById('overlay'),s=RunSave.summary();
    if(s){const slot=document.createElement('section');slot.className='continue-card';slot.innerHTML=`<div><span class="overline">自动保存的寻圣历程</span><strong>第${s.stage+1}难 · ${s.realm} · Lv.${s.level}</strong><small>${s.savedAt?new Date(s.savedAt).toLocaleString('zh-CN'):'旧版入口存档 · 将安全迁移'}</small></div><button class="btn" id="continueRunBtn">继续历程 →</button>`;ov.querySelector('.journey-menu').prepend(slot);document.getElementById('continueRunBtn').onclick=()=>RunSave.continueRun(Journey.run.heroId);const saved=RunSave.snapshot();}

    if(s){const start=document.getElementById('startBtn'),saved=RunSave.snapshot();const pending=saved&&(saved.run.queue>0||saved.run.chestReward||saved.run.pendingLore!==null&&saved.run.pendingLore!==undefined||saved.run.coreReward);start.textContent=pending?'请先继续历程 · 处理待领奖励':'以当前人物重战所选章节 →';start.disabled=!!pending;}
  }
  function frame(time){if(G.state!=='character'||!['stats','break'].includes(tab))return;const canvas=document.getElementById('heroPreview');if(canvas?.getContext)Motion.preview(canvas.getContext('2d'),time,P.cultivation,P.heroId);}
  return {init,toggle,close,draw,frame,coreRewardHTML,bindCoreReward,decorateMenu};
})();
